{
  "id": "V034",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "영어 독자가 이해할 수 있는 번역문을 만들고 편집자가 검토하려는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "번역, 고유명사·수치 누락 확인, 원문 대조 검토가 모두 반영됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "한국어 기사와 그 영어 번역문이 대상임."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어 기사 원문이 명시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 번역문이 명시됨."
    },
    {
      "field": "constraints",
      "score": 0,
      "reason": "원문에 없는 인용이나 성과를 추가하지 않고 게시 결정을 편집자가 한다는 조건이 모든 뷰에서 빠짐."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "뷰에 원문에 없는 기능 추가가 없음."
    },
    {
      "field": "roles",
      "score": 1,
      "reason": "편집자의 원문 대조 검토 역할은 보존되나 게시 결정 권한은 누락됨."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "원문에 없는 인용이나 성과를 추가하지 않으며",
      "view_quote": "",
      "reason": "번역문에 원문에 없는 인용이나 성과를 넣지 말라는 제약이 어느 뷰에도 없음."
    },
    {
      "type": "OMISSION",
      "source_quote": "게시 결정은 편집자가 합니다.",
      "view_quote": "",
      "reason": "게시 결정이 편집자의 권한이라는 점이 어느 뷰에도 없음."
    }
  ],
  "permission_interpretation": "편집자가 게시를 결정한다는 원문의 권한 배분은 보존되지 않았으며, 뷰는 AI가 게시한다고 주장하지도 않음."
}
